  Selector_output : PROCESS (Delay2_out1, lrnInPlusPadded_out1)
    VARIABLE add_temp : signed(31 DOWNTO 0);
    VARIABLE add_cast : unsigned(15 DOWNTO 0);
    VARIABLE add_temp_0 : unsigned(16 DOWNTO 0);
    VARIABLE sub_temp : unsigned(17 DOWNTO 0);
    VARIABLE sub_temp_0 : signed(31 DOWNTO 0);
    VARIABLE cast : unsigned(15 DOWNTO 0);
    VARIABLE sub_temp_1 : signed(31 DOWNTO 0);
  BEGIN
    add_temp := to_signed(16#00000000#, 32);
    add_temp_0 := to_unsigned(16#00000#, 17);
    sub_temp := to_unsigned(16#00000#, 18);
    sub_temp_0 := to_signed(16#00000000#, 32);
    sub_temp_1 := to_signed(16#00000000#, 32);
    add_cast := to_unsigned(16#0000#, 16);
    cast := to_unsigned(16#0000#, 16);

    FOR ii_select IN 0 TO 8 LOOP
      FOR ii2 IN 0 TO 26 LOOP
        add_temp := to_signed(ii_select + 1, 32);
        add_cast := unsigned(add_temp(15 DOWNTO 0));
        add_temp_0 := resize(Delay2_out1, 17) + resize(add_cast, 17);
        sub_temp := resize(add_temp_0, 18) - to_unsigned(16#00001#, 18);
        sub_temp_0 := to_signed(26 - ii2, 32);
        cast := unsigned(sub_temp_0(15 DOWNTO 0));
        sub_temp_1 := to_signed(27 - ii2, 32);
        IF (sub_temp = resize(cast, 18)) OR (sub_temp_1 = to_signed(16#0000001B#, 32)) THEN 
          Selector_out1(ii_select) <= lrnInPlusPadded_out1(26 - ii2);
        END IF;
      END LOOP;
    END LOOP;

  END PROCESS Selector_output;


